function htmlEntityDecode(str) {
  if (!str) return "";
  return String(str)
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
}

function stripTags(html) {
  if (!html) return "";
  let s = String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<\/?[^>]+>/g, " ");
  s = htmlEntityDecode(s);
  return s.replace(/\u00A0/g, " ").replace(/\s+/g, " ").trim();
}

function toAbsolute(url) {
  if (!url) return null;
  const u = String(url).trim();
  if (!u) return null;
  if (u.startsWith("http://") || u.startsWith("https://")) return u;
  if (u.startsWith("//")) return "https:" + u;
  if (u.startsWith("/")) return "https://www.boursorama.com" + u;
  return "https://www.boursorama.com/" + u;
}

function canonicalize(url) {
  if (!url) return null;
  return String(url).split("#")[0].split("?")[0];
}

function decodeDataRel(b64) {
  try {
    return Buffer.from(String(b64), "base64").toString("utf8") || null;
  } catch {
    return null;
  }
}

function isBoursoramaArticle(url) {
  if (!url) return false;
  const u = canonicalize(url);
  return (
    /^https:\/\/www\.boursorama\.com\/bourse\/actualites\/.+-[0-9a-f]{32}$/i.test(u) ||
    /^https:\/\/www\.boursorama\.com\/actualites\/.+-[0-9a-f]{32}$/i.test(u)
  );
}

function extractFromLiBlock(blockHtml) {
  const block = String(blockHtml);
  let relUrl = null;

  const hrefMatch = block.match(/<a\b[^>]*href="([^"]+)"/i);
  if (hrefMatch?.[1]) relUrl = hrefMatch[1];

  if (!relUrl) {
    const relMatches = [...block.matchAll(/\bdata-rel="([^"]+)"/gi)].map((m) => m[1]);
    for (const b64 of relMatches) {
      const decoded = decodeDataRel(b64);
      if (decoded && decoded.includes("/actualites/")) {
        relUrl = decoded;
        break;
      }
    }
  }

  const articleUrl = toAbsolute(relUrl);
  const articleCanonicalUrl = canonicalize(articleUrl);

  let title = block.match(/\btitle="([^"]+)"/i)?.[1] || null;
  if (!title) {
    title = block.match(/c-list-details-news__subject[^>]*>([\s\S]*?)<\/(?:a|span)>/i)?.[1] || null;
  }
  title = title ? stripTags(title) : null;

  const publishedAtGuess = stripTags(block.match(/c-source__time[^>]*>([^<]+)</i)?.[1] || "") || null;
  const snippetGuess =
    stripTags(
      block.match(
        /<p[^>]*class="[^"]*c-list-details-news__content[^"]*"[^>]*>([\s\S]*?)<\/p>/i
      )?.[1] || ""
    ) || null;

  return {
    articleUrl,
    articleCanonicalUrl,
    articleTitleGuess: title,
    publishedAtGuess,
    snippetGuess,
  };
}

const input = $input.first().json;
const html = input.listingHtml || input.body || input.html || input.response || "";
const actualitesUrl = input.actualitesUrl ? canonicalize(input.actualitesUrl) : null;

const dropped = {
  null_url: 0,
  not_article: 0,
  is_listing: 0,
  duplicate: 0,
};

const articles_raw = [];
const seen = new Set();

const liRe = /<li\b[^>]*class="[^"]*c-list-details-news__line[^"]*"[^>]*>([\s\S]*?)<\/li>/gi;
const liBlocks = [...html.matchAll(liRe)].map((m) => m[1]);

let extractionMethod = "li_blocks";

if (liBlocks.length === 0) {
  extractionMethod = "fallback_anchors";
  const re = /<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gsi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const articleUrl = toAbsolute(m[1]);
    const articleCanonicalUrl = canonicalize(articleUrl);
    const title = stripTags(m[2]) || null;

    if (!articleUrl) {
      dropped.null_url++;
      continue;
    }
    if (actualitesUrl && articleCanonicalUrl === actualitesUrl) {
      dropped.is_listing++;
      continue;
    }
    if (!isBoursoramaArticle(articleUrl)) {
      dropped.not_article++;
      continue;
    }
    if (seen.has(articleCanonicalUrl)) {
      dropped.duplicate++;
      continue;
    }

    seen.add(articleCanonicalUrl);
    articles_raw.push({
      articleUrl,
      articleCanonicalUrl,
      articleTitleGuess: title,
      publishedAtGuess: null,
      snippetGuess: null,
    });
  }
} else {
  for (const block of liBlocks) {
    const parsed = extractFromLiBlock(block);
    if (!parsed.articleUrl) {
      dropped.null_url++;
      continue;
    }
    if (actualitesUrl && parsed.articleCanonicalUrl === actualitesUrl) {
      dropped.is_listing++;
      continue;
    }
    if (!isBoursoramaArticle(parsed.articleUrl)) {
      dropped.not_article++;
      continue;
    }
    if (seen.has(parsed.articleCanonicalUrl)) {
      dropped.duplicate++;
      continue;
    }
    seen.add(parsed.articleCanonicalUrl);
    articles_raw.push(parsed);
  }
}

return [
  {
    json: {
      ...input,
      extractionMethod,
      candidates_total: liBlocks.length,
      filtered_total: articles_raw.length,
      dropped_reason_counts: dropped,
      articles_raw,
      articles_raw_count: articles_raw.length,
    },
  },
];

const crypto = require("crypto");

const LIMIT = 10;

function sha1(s) {
  return crypto.createHash("sha1").update(String(s), "utf8").digest("hex");
}

function parseListingDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();

  const fr = s.match(/(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})/);
  if (fr) {
    let year = Number(fr[3]);
    if (year < 100) year += 2000;
    const month = Number(fr[2]) - 1;
    const day = Number(fr[1]);
    const d = new Date(Date.UTC(year, month, day, 0, 0, 0));
    if (!isNaN(d.getTime())) return d.toISOString();
  }

  const iso = new Date(s);
  if (!isNaN(iso.getTime())) return iso.toISOString();
  return null;
}

function canonical(url) {
  return String(url || "").split("#")[0].split("?")[0];
}

return $input.all().map((inItem) => {
  const item = inItem.json || {};
  const raw = Array.isArray(item.articles_raw) ? item.articles_raw : [];
  const symbol = String(item.symbol || "").toUpperCase();

  const uniq = new Map();

  for (const a of raw) {
    const articleCanonicalUrl = canonical(a.articleCanonicalUrl || a.articleUrl || "");
    if (!articleCanonicalUrl) continue;

    const newsId = sha1(`${symbol}|${articleCanonicalUrl}`);
    if (uniq.has(newsId)) continue;

    const publishedAtGuess = parseListingDate(a.publishedAtGuess);

    uniq.set(newsId, {
      newsId,
      articleUrl: a.articleUrl || articleCanonicalUrl,
      articleCanonicalUrl,
      articleTitleGuess: a.articleTitleGuess || null,
      publishedAtGuess,
      publishedAtTs: publishedAtGuess ? new Date(publishedAtGuess).getTime() : null,
      snippetGuess: a.snippetGuess || null,
    });
  }

  const articles = Array.from(uniq.values())
    .sort((a, b) => {
      const x = a.publishedAtTs ?? -1;
      const y = b.publishedAtTs ?? -1;
      return y - x;
    })
    .slice(0, LIMIT)
    .map((a, idx) => {
      const { publishedAtTs, ...rest } = a;
      return { ...rest, articleOrder: idx + 1 };
    });

  const hasArticles = articles.length > 0;

  return {
    json: {
      ...item,
      articles,
      articles_count: articles.length,
      hasArticles,
      _articlesStatus: hasArticles ? "HAS_ARTICLES" : "NO_ARTICLES",
      articles_limit: LIMIT,
    },
    pairedItem: inItem.pairedItem,
  };
});

const out = [];

for (const it of $input.all()) {
  const base = it.json || {};
  const articles = Array.isArray(base.articles) ? base.articles : [];

  const baseCtx = { ...base };
  delete baseCtx.articles;
  delete baseCtx.articles_raw;
  delete baseCtx.listingHtml;

  let first = true;
  for (const article of articles) {
    const articleUrl = article.articleUrl || article.articleCanonicalUrl || null;
    if (!articleUrl) continue;

    const articleCanonicalUrl =
      article.articleCanonicalUrl || String(articleUrl).split("#")[0].split("?")[0];

    out.push({
      json: {
        ...baseCtx,
        newsId: article.newsId || null,
        articleUrl,
        articleCanonicalUrl,
        url: articleUrl,
        canonicalUrl: articleCanonicalUrl,
        articleTitleGuess: article.articleTitleGuess || null,
        publishedAtGuess: article.publishedAtGuess || null,
        snippetGuess: article.snippetGuess || null,
        _articlesLoopReset: first === true,
        _status: "HAS_ARTICLE",
      },
    });

    first = false;
  }
}

return out;

const crypto = require("crypto");

function hash(s) {
  return crypto.createHash("sha1").update(String(s), "utf8").digest("hex");
}

function compactJson(obj) {
  try {
    return JSON.stringify(obj);
  } catch {
    return String(obj);
  }
}

const j = $json || {};
const nowIso = new Date().toISOString();

const stage = j._errorStage || (j.articleUrl ? "article_fetch" : "listing_fetch");
const url = j.articleUrl || j.articleCanonicalUrl || j.actualitesUrl || j.url || "";
const httpCode = Number.isFinite(Number(j.statusCode)) ? Number(j.statusCode) : null;

const message =
  j.error?.message ||
  j.errorMessage ||
  j.notes ||
  (httpCode && httpCode !== 200 ? `HTTP_${httpCode}` : "unknown_error");

const signature = [
  j.run_id || "no_run",
  stage,
  j.symbol || "no_symbol",
  url || "no_url",
  httpCode || "no_code",
  String(message).slice(0, 120),
  nowIso.slice(0, 16),
].join("|");

return [
  {
    json: {
      errorId: hash(signature),
      run_id: j.run_id || "",
      db_path: j.db_path || "/files/duckdb/ag4_spe_v2.duckdb",
      stage,
      symbol: j.symbol || "",
      companyName: j.companyName || "",
      url,
      httpCode,
      message: String(message),
      rawError: compactJson({
        statusCode: j.statusCode,
        error: j.error || null,
        responseHeaders: j.headers || null,
