import duckdb
import gc
import hashlib
import time
from contextlib import contextmanager
from datetime import date, datetime, timezone

DEFAULT_DB_PATH = "/files/duckdb/ag4_spe_v2.duckdb"


@contextmanager
def db_con(path=DEFAULT_DB_PATH, retries=8, delay=1):
    con = None
    for attempt in range(retries):
        try:
            con = duckdb.connect(path)
            break
        except Exception as exc:
            if "lock" in str(exc).lower() and attempt < retries - 1:
                time.sleep(delay * (2 ** attempt))
            else:
                raise
    try:
        yield con
    finally:
        if con is not None:
            # No per-run CHECKPOINT here: on multi-GB DuckDB files it can exceed n8n task timeouts.
            try:
                con.close()
            except Exception:
                pass
        gc.collect()


def to_int(v, d=0):
    try:
        if v is None or v == "":
            return d
        return int(round(float(v)))
    except Exception:
        return d


def to_text(v):
    if v is None:
        return ""
    return str(v)


def to_bool(v, d=True):
    if isinstance(v, bool):
        return v
    if v is None:
        return d
    s = str(v).strip().lower()
    if s in ("1", "true", "yes", "y"):
        return True
    if s in ("0", "false", "no", "n"):
        return False
    return d


def ensure_utc(dt):
    if dt is None:
        return None
    if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def parse_ts(v):
    if v is None:
        return None
    if isinstance(v, (datetime, date)):
        if isinstance(v, date) and not isinstance(v, datetime):
            return datetime(v.year, v.month, v.day, tzinfo=timezone.utc)
        return ensure_utc(v)

    s = str(v).strip()
    if not s:
        return None
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"

    try:
        return ensure_utc(datetime.fromisoformat(s))
    except Exception:
        pass

    try:
        d = datetime.strptime(s, "%d.%m.%Y")
        return ensure_utc(d)
    except Exception:
        return None


def build_news_id(symbol, canonical_url):
    seed = f"{str(symbol or '').upper()}|{str(canonical_url or '')}"
    return hashlib.sha1(seed.encode("utf-8")).hexdigest()


items = _items or []
if len(items) == 0:
